def minCoinsLimited(coins, counts, amount):
    INF = float("inf")
    best = [INF] * (amount + 1)
    best[0] = 0
    for c, k in zip(coins, counts):
        piece = 1
        while k > 0:
            t = min(piece, k)
            k -= t
            piece *= 2
            w = c * t
            for s in range(amount, w - 1, -1):
                cand = best[s - w] + t
                if cand < best[s]:
                    best[s] = cand
    return -1 if best[amount] == INF else best[amount]
